<?php require 'db.php'; require_login(); $uid=(int)current_user()['user_id']; $s=$pdo->prepare('SELECT u.*,p.phone,p.shipping_address,p.billing_address FROM users u LEFT JOIN profiles p ON p.user_id=u.user_id WHERE u.user_id=?');$s->execute([$uid]);$u=$s->fetch();$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$shipping=trim($_POST['shipping_address']??'');$billing=trim($_POST['billing_address']??'');if($name===''||strlen($name)>100)$error='Please enter a valid name.';else{$pdo->beginTransaction();$s=$pdo->prepare('UPDATE users SET name=?,contact=?,address=? WHERE user_id=?');$s->execute([$name,$phone,$shipping,$uid]);$s=$pdo->prepare('INSERT INTO profiles(user_id,phone,shipping_address,billing_address) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE phone=VALUES(phone),shipping_address=VALUES(shipping_address),billing_address=VALUES(billing_address)');$s->execute([$uid,$phone,$shipping,$billing]);$pdo->commit();$_SESSION['user']['name']=$name;header('Location: profile.php?saved=1');exit;}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Profile | Ceylon Spice Hub</title><link rel="stylesheet" href="style.css"></head><body><header class="header"><div class="container nav-wrap"><a class="brand" href="index.php"><span>Ceylon</span><small>SPICE HUB</small></a><nav><a href="index.php">Home</a><a href="index.php#shop">Shop</a><a class="active" href="profile.php">Profile</a><a href="cart.php">Cart</a></nav><a class="btn btn-light" href="logout.php">Logout</a></div></header><main class="profile-page"><div class="container profile-grid"><aside class="profile-side"><div class="avatar"><?=e(strtoupper(substr($u['name'],0,1)))?></div><h2><?=e($u['name'])?></h2><p><?=e($u['email'])?></p><span class="status-badge">● Active Member</span><a href="cart.php" class="profile-link">Shopping Cart →</a><a href="logout.php" class="profile-link">Log out →</a></aside><section class="profile-content"><p class="eyebrow">MY ACCOUNT</p><h1>Profile & Settings</h1><p class="muted">Keep your contact and delivery information up to date for faster checkout.</p><?php if($error):?><div class="form-error"><?=e($error)?></div><?php elseif(isset($_GET['saved'])):?><div class="form-success">Your profile details have been saved.</div><?php endif;?><div class="profile-card"><h2>Account Details</h2><p class="small-muted">Member since <?=e(date('F j, Y',strtotime($u['created_at'])))?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><label>Full Name<input name="name" value="<?=e($u['name'])?>" required></label><label>Email<input value="<?=e($u['email'])?>" disabled></label><label>Phone Number<input name="phone" value="<?=e($u['phone']??$u['contact']??'')?>" placeholder="+94 7X XXX XXXX"></label></div><label>Shipping Address<textarea name="shipping_address" rows="3" placeholder="House number, street, city"><?=e($u['shipping_address']??$u['address']??'')?></textarea></label><label>Billing Address<textarea name="billing_address" rows="3" placeholder="Optional billing address"><?=e($u['billing_address']??'')?></textarea></label><button class="btn btn-primary">SAVE DETAILS</button></form></div><div class="profile-security"><div><b>🔐 Password security</b><span>Your password is stored using bcrypt hashing and is never shown as plain text.</span></div><a href="change_password.php" class="btn btn-light">CHANGE PASSWORD</a></div></section></div></main></body></html>